<?php
namespace Tests\Feature;
use App\Models\FounderInterestRequest;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class PrelaunchTest extends TestCase {use RefreshDatabase;private function payload():array{return ['business_name'=>'Destino fundador','contact_name'=>'Ana Responsable','email'=>'ana@example.com','phone'=>'7000-0000','relationship_role'=>'owner','department'=>'La Libertad','website'=>'https://example.com','message'=>'Deseamos verificar la información y aportar fotografías autorizadas del lugar.','privacy'=>'1','fax_number'=>''];}
 public function test_public_program_explains_scope_and_collects_consented_request():void{$this->seed();$this->get(route('founder-program.show'))->assertOk()->assertSee('no garantiza publicación',false);$this->post(route('founder-program.store'),$this->payload())->assertSessionHasNoErrors();$request=FounderInterestRequest::first();$this->assertSame('new',$request->status);$this->assertNotNull($request->privacy_accepted_at);$this->assertNotNull($request->public_id);}
 public function test_request_requires_privacy_and_honeypot_stays_empty():void{$this->seed();$payload=$this->payload();unset($payload['privacy']);$payload['fax_number']='spam';$this->post(route('founder-program.store'),$payload)->assertSessionHasErrors(['privacy','fax_number']);$this->assertDatabaseCount('founder_interest_requests',0);}
 public function test_only_admin_manages_prelaunch_pipeline():void{$this->seed();$this->post(route('founder-program.store'),$this->payload());$item=FounderInterestRequest::first();$traveler=User::factory()->create(['email_verified_at'=>now()]);$admin=User::factory()->create(['role'=>'admin','email_verified_at'=>now()]);$this->actingAs($traveler)->get(route('admin.prelaunch.index'))->assertForbidden();$this->actingAs($admin)->get(route('admin.prelaunch.index'))->assertOk()->assertSee('Lista de preparación')->assertSee('Destino fundador');$this->put(route('admin.prelaunch.update',$item),['status'=>'contacted','admin_notes'=>'Contacto inicial realizado.'])->assertSessionHasNoErrors();$this->assertSame('contacted',$item->fresh()->status);$this->assertSame($admin->id,$item->fresh()->assigned_to);$this->assertNotNull($item->fresh()->contacted_at);}
}
